using System;using System.IO;using System.Linq;using System.Text;using System.Reflection;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering;
[InitializeOnLoad]public static class FinalCitySignsFinish{
const string Dir="Assets/Scenes/Oasis/CityBuildingSigns",Group="City Building Signs - Shared Atlas";
static BindingFlags F=BindingFlags.Static|BindingFlags.NonPublic;static Type T=typeof(FinalCitySigns);static object C(string n,params object[] a)=>T.GetMethod(n,F).Invoke(null,a);static V Get<V>(object o,string n)=>(V)o.GetType().GetField(n).GetValue(o);static void Set(object o,string n,object v)=>o.GetType().GetField(n).SetValue(o,v);
static FinalCitySignsFinish(){EditorApplication.update+=Poll;}static void Poll(){if(!File.Exists("FinalCitySignsFinish.request")||EditorApplication.isCompiling)return;File.Delete("FinalCitySignsFinish.request");Run();}
static void Photo(Scene s,Vector3 p,Vector3 target,string n)=>typeof(FinalPNGCityDetails).GetMethod("Capture",F).Invoke(null,new object[]{s,p,target,n});
static bool RoadView(Array all,Vector3[] roads,Vector3 target,Vector3 normal,out Vector3 camera){foreach(var road in roads.Where(v=>Vector3.Dot(v-target,normal)>4&&new Vector2(v.x-target.x,v.z-target.z).magnitude<170).OrderBy(v=>(v-target).sqrMagnitude).Take(35)){var p=new Vector3(road.x,31.2f,road.z);var direction=(target-p).normalized;float distance=Vector3.Distance(target,p);bool blocked=false;foreach(var g in all){var b=Get<Bounds>(g,"bounds");if(!b.IntersectRay(new Ray(p,direction),out float near)||near>=distance-.15f)continue;object[] args={g,p,direction,Vector3.zero,Vector3.zero};if((bool)C("Hit",args)&&Vector3.Distance(p,(Vector3)args[3])<distance-.15f){blocked=true;break;}}if(!blocked){camera=p;return true;}}camera=Vector3.zero;return false;}
class Display{public Vector3 p,n;public int art;public Transform owner;}
static void Run(){var log=new StringBuilder();try{var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var group=scene.GetRootGameObjects().Single(g=>g.name==Group);var controller=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CityDayNightController>(true)).First();var roads=controller.streetLightPositions;
var native=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>(true)).Where(r=>r.enabled&&r.gameObject.activeInHierarchy&&r.sharedMaterials.Any(m=>m&&m.name.StartsWith("Building"))&&r.GetComponent<MeshFilter>()&&r.bounds.size.y>7&&r.bounds.size.y<180&&r.bounds.size.x>5&&r.bounds.size.z>5&&r.bounds.size.x<180&&r.bounds.size.z<180).ToArray();var gt=T.GetNestedType("Geo",BindingFlags.NonPublic);var all=Array.CreateInstance(gt,native.Length);for(int i=0;i<native.Length;i++)all.SetValue(C("Read",native[i]),i);var bt=T.GetNestedType("B",BindingFlags.NonPublic);var st=T.GetNestedType("Site",BindingFlags.NonPublic);var mat=AssetDatabase.LoadAssetAtPath<Material>(Dir+"/City Shared Sign Atlas.mat");int added=0;
for(int i=0;i<all.Length;i++){var g=all.GetValue(i);var bounds=Get<Bounds>(g,"bounds");if(group.transform.Cast<Transform>().Any(t=>Vector3.Distance(t.position,bounds.center)<.01f))continue;var directions=(Vector3[])C("Directions",g,roads);object site=C("Wall",g,directions,2.2f,1.3f,"Badge",20+i%4,all,roads,null);if(site==null){var p=Get<Vector3[]>(g,"p");var ids=Get<int[]>(g,"ids");foreach(int k in Enumerable.Range(0,ids.Length/3).OrderByDescending(k=>(p[ids[k*3]].y+p[ids[k*3+1]].y+p[ids[k*3+2]].y)/3)){var a=p[ids[k*3]];var b=p[ids[k*3+1]];var d=p[ids[k*3+2]];var normal=Vector3.Cross(b-a,d-a).normalized;if(Mathf.Abs(normal.y)<.90f||Vector3.Cross(b-a,d-a).magnitude<4)continue;var center=(a+b+d)/3;var n=directions[0];var target=center+Vector3.up*2;if(!RoadView(all,roads,target,n,out _))continue;site=Activator.CreateInstance(st,true);Set(site,"g",g);Set(site,"p",target);Set(site,"n",n);Set(site,"w",2.2f);Set(site,"h",2.2f);Set(site,"art",20+i%4);Set(site,"kind","Roof");break;}}
if(site==null){log.AppendLine("No supported road-visible sign: "+Get<MeshRenderer>(g,"r").name);continue;}var builder=Activator.CreateInstance(bt,true);bt.GetMethod("Board").Invoke(builder,new object[]{site,true});if(Get<string>(site,"kind")=="Roof"){var normal=Get<Vector3>(site,"n");var right=Vector3.Cross(Vector3.up,normal);var center=Get<Vector3>(site,"p")-Vector3.up*1.5f;foreach(float x in new[]{-.65f,.65f})bt.GetMethod("Box").Invoke(builder,new object[]{center+right*x,right,Vector3.up,normal,.10f,1.1f,.10f,new Color(.04f,.045f,.05f,0)});}var mesh=(Mesh)bt.GetMethod("Mesh").Invoke(builder,new object[]{"Supplementary Signs "+i,bounds.center});int number=group.transform.childCount;AssetDatabase.CreateAsset(mesh,Dir+"/Meshes/Signs-"+number.ToString("000")+".asset");var go=new GameObject("Signs "+number.ToString("000")+" - "+Get<MeshRenderer>(g,"r").name);go.transform.SetParent(group.transform,false);go.transform.position=bounds.center;go.AddComponent<MeshFilter>().sharedMesh=mesh;var r=go.AddComponent<MeshRenderer>();r.sharedMaterial=mat;r.shadowCastingMode=ShadowCastingMode.Off;r.receiveShadows=false;r.lightProbeUsage=LightProbeUsage.Off;var lod=go.AddComponent<LODGroup>();lod.SetLODs(new[]{new LOD(.045f,new Renderer[]{r})});lod.RecalculateBounds();lod.size=Mathf.Clamp(lod.size,8,24);GameObjectUtility.SetStaticEditorFlags(go,StaticEditorFlags.BatchingStatic|StaticEditorFlags.OccludeeStatic);PrefabUtility.SaveAsPrefabAssetAndConnect(go,Dir+"/Prefabs/Building Signs "+number.ToString("000")+".prefab",InteractionMode.AutomatedAction);added++;}
AssetDatabase.SaveAssets();PrefabUtility.SaveAsPrefabAssetAndConnect(group,Dir+"/City Building Signs.prefab",InteractionMode.AutomatedAction);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);
var displays=new List<Display>();foreach(var f in group.GetComponentsInChildren<MeshFilter>()){var m=f.sharedMesh;var colors=m.colors;var p=m.vertices;var uv=m.uv;for(int j=0;j<p.Length;j+=4){if(colors[j].a<.4f||colors[j].a>.6f)continue;var mid=(p[j]+p[j+1]+p[j+2]+p[j+3])*.25f;float v=(uv[j].y+uv[j+2].y)*.5f;float u=(uv[j].x+uv[j+2].x)*.5f;int row=v>.82f?0:v>.66f?1:v>.5f?2:-1;if(row<0)continue;var n=Vector3.Cross(p[j+1]-p[j],p[j+2]-p[j]).normalized;displays.Add(new Display{p=f.transform.TransformPoint(mid),n=f.transform.TransformDirection(n),art=row*4+Mathf.FloorToInt(u*4),owner=f.transform});}}
bool night=controller.IsNight;var chosen=new List<Display>();try{int index=0;foreach(var target in new[]{new Vector3(230,45,-45),new Vector3(-120,45,-250),new Vector3(540,45,160),new Vector3(430,45,-320)}){foreach(var s in displays.Where(v=>!chosen.Contains(v)).OrderBy(v=>(v.p-target).sqrMagnitude).Take(50)){if(!RoadView(all,roads,s.p,s.n,out var camera))continue;index++;chosen.Add(s);controller.ApplyDay();Photo(scene,camera,s.p,"City-Signs-Day-"+index);controller.ApplyNight();Photo(scene,camera,s.p,"City-Signs-Night-"+index);log.AppendLine("VIEW "+index+" building="+s.owner.name+" art="+s.art+" road camera="+camera);break;}}
var clothing=displays.Where(d=>d.art==11).FirstOrDefault(d=>RoadView(all,roads,d.p,d.n,out _));if(clothing!=null&&RoadView(all,roads,clothing.p,clothing.n,out var cam)){controller.ApplyDay();Photo(scene,cam,clothing.p,"City-Signs-Clothing");}if(chosen.Count!=4)throw new Exception("Only "+chosen.Count+" unobstructed previews");
}finally{if(night)controller.ApplyNight();else controller.ApplyDay();}
int errors=ShaderUtil.GetShaderMessages(mat.shader).Count(v=>v.severity.ToString()=="Error");if(errors>0)throw new Exception("Shader errors="+errors);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);log.AppendLine("SUCCESS added compact supported signs="+added+"; total building prefabs="+group.transform.childCount+"; one atlas/material; four unobstructed day/night road-view previews; clothing ad preview; shader errors=0");
}catch(Exception e){log.AppendLine("FAILED "+e);Debug.LogException(e);}File.WriteAllText("FinalEnvironmentRoadReview/CitySignsFinishReport.txt",log.ToString());}}
